sys_script_include.script:
var PatientUtils = Class.create();
PatientUtils.prototype = {
    initialize: function() {},

    fetchAllPatientDetailsByPatientId: function(id) {
        var patient = new GlideRecord('u_patient_record');
        patient.addQuery('u_number', id);
        patient.query();
        if (patient.next()) {
            return patient;
        } else {
            return null;
        }
    },

    checkIfPatientIsVip: function(id) {
        var patient = new GlideRecord('u_patient_record');
        patient.get(id)
        if (patient.u_vip) {
            return "Patient Is VIP.";
        } else {
            return "Patient is not VIP"
        }
    },

    calculatePatientAge: function(id) {
        var patient = new GlideRecord('u_patient_record');
        patient.addQuery('u_number', id);
        patient.query();
        if (patient.next()) {
            var age = gs.dateDiff(patient.u_date_of_birth, gs.now(), true);
            return Math.floor(age / (24 * 60 * 60 * 365));
        } else {
            return "Patient not found."
        }

    },

    fetchPatientAppointments: function(patientid) {
        var appoint = new GlideRecord('u_appointment');
        appoint.addQuery('u_patient_id', patientid);
        appoint.query();
        return appoint;
    },


    fetchPatientMedications: function(patientid) {
        var medicine = new GlideRecord('u_medication');
        medicine.addQuery('u_patient_id', patientid);
        medicine.query();
        return medicine;
    },

    fetchPatientLabTest: function(patientid) {
        var labTest = new GlideRecord('u_lab_test');
        labTest.addQuery('u_patient_id', patientid);
        labTest.query();
        return labTest;
    },

    fetchPatientBillingRecord: function(patientid) {
        var bill = new GlideRecord('u_billing');
        bill.addQuery('u_patient_id', patientid);
        bill.query();
        return bill;
    },

    fetchPatientInsurancePolicies: function(patientid) {
        var insurance = new GlideRecord('u_insurance');
        insurance.addQuery('u_patient_id', patientid);
        insurance.query();
        return insurance;
    },


    type: 'PatientUtils'
};
